Algorithm Caja
  Dimension nombres[5] As String;
  Dimension precios[5] As Integer;
  Dimension unidades[5] As Integer;
  nombres[0] <- "Jugo";
  nombres[1] <- "Sándwich";
  nombres[2] <- "Alfajor";
  nombres[3] <- "Agua";
  nombres[4] <- "Fruta";
  precios[0] <- 3;
  precios[1] <- 5;
  precios[2] <- 2;
  precios[3] <- 1;
  precios[4] <- 2;
  For i <- 0 To 4 Do
    unidades[i] <- 0;
  EndFor
  Define total As Integer <- 0;
  Define codigo As Integer;
  Define cantidad As Integer;
  Read codigo;
  While codigo <> 0 Do
    Read cantidad;
    If codigo < 1 Or codigo > 5 Then
      Write "Código ", codigo, " no existe";
    Else
      Define importe As Integer <- precios[codigo - 1] * cantidad;
      Write nombres[codigo - 1], " x ", cantidad, " = ", importe;
      total <- total + importe;
      unidades[codigo - 1] <- unidades[codigo - 1] + cantidad;
    EndIf
    Read codigo;
  EndWhile
  Write "Total: ", total;
  Write "Con descuento: ", total - total Div 10;
  Define mejor As Integer <- -1;
  For i <- 0 To 4 Do
    If unidades[i] > 0 Then
      If mejor = -1 Then
        mejor <- i;
      Else
        If unidades[i] > unidades[mejor] Then
          mejor <- i;
        EndIf
      EndIf
    EndIf
  EndFor
  If mejor = -1 Then
    Write "Más vendido: Ninguno";
  Else
    Write "Más vendido: ", nombres[mejor];
  EndIf
EndAlgorithm
